"""Reject redundant outer document markers without touching inter-document separators."""

from __future__ import annotations

import re
import sys

from common import ROOT, owned, tracked

# Generated by the pinned external qg compiler; qg validate owns their exact bytes.
GENERATED = {
    f".github/workflows/quality-graph{suffix}.yml"
    for suffix in ("", "-push", "-publish")
}
MARKER = re.compile(rb"(---|\.\.\.)(?:[ \t]+(#[^\r\n]*))?[ \t]*(\r?\n)?$")


def redundant(lines: list[bytes]) -> list[int]:
    """Inspect outer syntax only; never strip indented scalar content or empty documents."""
    content = [
        i
        for i, line in enumerate(lines)
        if line.strip() and not line.lstrip().startswith(b"#")
    ]
    if not content:
        return []
    first, last = content[0], content[-1]
    result = []
    if (
        MARKER.fullmatch(lines[first])
        and lines[first].startswith(b"---")
        and len(content) > 1
    ):
        following = lines[content[1]]
        if not MARKER.fullmatch(following) and not following.startswith(
            (b"--- ", b"%")
        ):
            result.append(first)
    if MARKER.fullmatch(lines[last]) and lines[last].startswith(b"..."):
        result.append(last)
    return result


def targets() -> list[str]:
    """Use the same verified source ownership boundary as other quality gates."""
    return [
        name
        for name in owned(tracked())
        if name.endswith((".yaml", ".yml"))
        and name not in GENERATED
        and not (ROOT / name).is_symlink()
    ]


def main() -> int:
    """Report paths and lines only, never contents."""
    errors = [
        f"{name}:{i + 1}: redundant YAML document marker"
        for name in targets()
        for i in redundant((ROOT / name).read_bytes().splitlines(keepends=True))
    ]
    for error in errors:
        sys.stderr.write(f"{error}\n")
    return int(bool(errors))


if __name__ == "__main__":
    raise SystemExit(main())
